1	// Shared server-upgrade (RESIZE up) core — used by the wallet flow
2	// (lib/actions-server.ts resizeServer) and by the Stripe confirm route so a paid
3	// checkout can apply the upgrade immediately. Plain server module (not "use server").
4	import { db } from "./db";
5	import { debitWallet, InsufficientBalanceError } from "./wallet";
6	import { invoiceCreateData } from "./invoices";
7	import { prorateUpgradeCents, remainingMonths } from "./proration";
8	
9	/** Average calendar month in ms (365.25/12 ≈ 30.44d) for duration-based proration. */
10	export const MS_PER_AVG_MONTH = 30.44 * 86400_000;
11	
12	export class ResizeError extends Error {}
13	
14	type QuotedServer = Awaited<ReturnType<typeof loadServer>>;
15	type QuotedPlan = NonNullable<Awaited<ReturnType<typeof loadPlan>>>;
16	
17	function loadServer(serverId: string) {
18	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
19	}
20	function loadPlan(planId: string) {
21	  return db.plan.findUnique({ where: { id: planId } });
22	}
23	
24	export type ResizeQuote = {
25	  server: NonNullable<QuotedServer>;
26	  newPlan: QuotedPlan;
27	  prorateCents: number;
28	};
29	
30	/**
31	 * Validate an UPGRADE and compute the prorated charge over the ACTUAL remaining
32	 * duration (monthly price difference for every remaining month; null expiresAt
33	 * on free/admin servers => 0). Throws ResizeError with a user-facing message on
34	 * any guard failure. Does NOT check ownership — callers must do that.
35	 *
36	 * ─── INTERACTION WITH PER-SERVER EXTRA DISK ─────────────────────────────────
37	 * `Server.extraDiskGB` (disk bought via the deploy upsell or "Add storage") is
38	 * ADDITIVE to whichever plan the server is on, so a plan change must leave it
39	 * completely alone. Two things follow, and both are deliberate:
40	 *
41	 *  1. NOT DOUBLE-CHARGED. The proration below is a difference of PLAN monthly
42	 *     prices. The extra-disk surcharge is identical before and after the resize
43	 *     (same GB, same per-GB price), so it cancels out of the delta exactly — it
44	 *     must never be added here. It keeps being billed, unchanged, by the renewal
45	 *     sweep, which reads `extraDiskGB` directly.
46	 *  2. NOT LOST. Nothing in the resize path writes `extraDiskGB`, and the worker's
47	 *     RESIZE handler sizes the disk to `newPlan.diskGB + server.extraDiskGB` — so
48	 *     the customer keeps every GB they paid for. (Sizing to the bare plan disk
49	 *     would ask Proxmox to SHRINK the disk of any server holding extra storage,
50	 *     and the whole resize would hard-fail.)
51	 *
52	 * The disk-grow guard below intentionally compares PLAN disks, not effective
53	 * disks: since the extra is added to both sides, a target plan with an equal or
54	 * larger disk can never shrink the effective disk.
55	 */
56	export async function resizeQuote(serverId: string, planId: string): Promise<ResizeQuote> {
57	  const server = await loadServer(serverId);
58	  if (!server) throw new ResizeError("Not found");
59	  const newPlan = await loadPlan(planId);
60	  if (!newPlan?.active) throw new ResizeError("Plan not available.");
61	  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
62	  if (newPlan.diskGB < server.plan.diskGB) {
63	    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
64	  }
65	  if (newPlan.priceCents < server.plan.priceCents) {
66	    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
67	  }
68	  if (!["RUNNING", "STOPPED"].includes(server.status)) throw new ResizeError("Server is busy.");
69	
70	  let prorateCents = 0;
71	  if (!server.isFree && server.expiresAt) {
72	    // Price the upgrade the way a FRESH order for the target plan would be priced
73	    // today — term discount AND current promo applied. Using the raw list-price
74	    // delta (as this did until 2026-07-25) overcharged by the whole discount
75	    // stack: on a 36-month term with a 30% promo running, $1,044.45 to upgrade
76	    // versus $665.08 to simply buy the same plan outright for the same end date.
77	    // Shared with the downgrade credit and with the client picker via
78	    // lib/proration.ts so displayed, charged and credited cannot drift apart.
79	    prorateCents = prorateUpgradeCents({
80	      fromMonthlyCents: server.plan.priceCents,
81	      toMonthlyCents: newPlan.priceCents,
82	      termMonths: server.termMonths,
83	      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
84	    });
85	  }
86	  return { server, newPlan, prorateCents };
87	}
88	
89	/**
90	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
91	 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
92	 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
93	 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
94	 * unauthenticated confirm route. Throws ResizeError on any guard failure.
95	 *
96	 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
97	 * amount the customer paid into their wallet at checkout so the debit here nets to
98	 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
99	 * spend the just-credited funds). The wallet path omits it and debits the quote.
100	 */
101	export async function applyResize(opts: {
102	  serverId: string;
103	  planId: string;
104	  actorUserId: string;
105	  chargeCents?: number;
106	}): Promise<void> {
107	  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
108	  const prorateCents = opts.chargeCents ?? quoted;
109	
110	  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
111	  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");
112	
113	  try {
114	    await db.$transaction(async (tx) => {
115	      if (prorateCents > 0) {
116	        await debitWallet(tx, server.userId, prorateCents);
117	        await tx.walletTransaction.create({
118	          data: {
119	            userId: server.userId,
120	            amountCents: -prorateCents,
121	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
122	          },
123	        });
124	        // PAID invoice for the proration charge (one per user-initiated resize).
125	        await tx.invoice.create({
126	          data: invoiceCreateData({
127	            userId: server.userId,
128	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
129	            status: "PAID",
130	            lineItems: [
131	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
132	            ],
133	          }),
134	        });
135	      }
136	      // Record the amount charged on the job so the worker's RESIZE handler can
137	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
138	      // resize terminally fails — money is committed here, before the job runs.
139	      await tx.job.create({
140	        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
141	      });
142	      await tx.auditLog.create({
143	        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
144	      });
145	    });
146	  } catch (e) {
147	    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
148	    throw e;
149	  }
150	}
151

120	  await db.job.create({ data: { type: "REINSTALL", serverId } });
121	  await db.auditLog.create({
122	    data: {
123	      userId: user.id,
124	      action: "server.reinstall_os",
125	      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
126	    },
127	  });
128	  revalidatePath(`/dashboard/servers/${serverId}`);
129	  return {};
130	}
131	
132	// ---------- 3. Resize-down ----------
133	
134	/**
135	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
136	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
137	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
138	 * otherwise). A prorated credit for the price difference over the remaining term
139	 * is returned to the wallet.
140	 */
141	export async function resizeServerDown(
142	  serverId: string,
143	  newPlanId: string
144	): Promise<{ error?: string }> {
145	  const { user, server } = await ownedServer(serverId);
146	
147	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
148	  if (!newPlan?.active) return { error: "Plan not available." };
149	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
150	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
151	
152	  // This action is downgrades only — upgrades go through resizeServer().
153	  if (newPlan.priceCents >= server.plan.priceCents) {
154	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
155	  }
156	  // Disk can't shrink destructively; block the move rather than lose data.
157	  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
158	  // both the old and the new plan and is preserved verbatim across the resize, so
159	  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
160	  // does not shrink". Nothing here ever writes extraDiskGB.
161	  if (newPlan.diskGB < server.plan.diskGB) {
162	    return {
163	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
164	    };
165	  }
166	
167	  if (await hasInflightJob(serverId)) {
168	    return { error: "Another operation is already in progress on this server." };
169	  }
170	
171	  // Credit at the SAME effective rate the upgrade path charges at — term discount
172	  // and promo applied — and clamp the remaining months to one term.
173	  //
174	  // The old maths credited the raw LIST-price delta over an UNCLAMPED duration,
175	  // so it refunded more than the customer had ever paid (they bought at the
176	  // term-discounted, promo-reduced price) and multiplied that by every month a
177	  // stacked `renewNow` had pushed `expiresAt` into the future. On a 36-month term
178	  // that is roughly a 20% cash windfall per downgrade before any promo. It has
179	  // been unreachable only because the disk-monotonic guard blocks every downgrade
180	  // the live catalogue permits — one cheap, storage-heavy plan would have turned
181	  // it into a self-service money printer. Shared with the upgrade path through
182	  // lib/proration.ts so the two directions can never drift apart again.
183	  let creditCents = 0;
184	  if (!server.isFree && server.expiresAt) {
185	    creditCents = prorateDowngradeCreditCents({
186	      fromMonthlyCents: server.plan.priceCents,
187	      toMonthlyCents: newPlan.priceCents,
188	      termMonths: server.termMonths,
189	      monthsRemaining: remainingMonths(server.expiresAt, Date.now(), server.termMonths),
190	    });
191	  }
192	
193	  await db.$transaction([
194	    ...(creditCents > 0
195	      ? [
196	          db.user.update({
197	            where: { id: server.userId },
198	            data: { balanceCents: { increment: creditCents } },
199	          }),
200	          db.walletTransaction.create({
201	            data: {
202	              userId: server.userId,
203	              amountCents: creditCents,
204	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
205	            },
206	          }),
207	        ]
208	      : []),
209	    // Record the amount credited on the job so the worker's RESIZE handler can
210	    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
211	    // terminally fails — the credit is committed here, before the job runs.
212	    // INTEGRATION NEEDED: worker must honour payload.prorateCents/direction.
213	    db.job.create({
214	      data: {
215	        type: "RESIZE",
216	        serverId,
217	        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
218	      },
219	    }),
220	    db.auditLog.create({
221	      data: {
222	        userId: user.id,
223	        action: "server.resize_down",
224	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
225	      },
226	    }),
227	  ]);
228	
229	  revalidatePath(`/dashboard/servers/${serverId}`);
230	  return {};
231	}
