611	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
612	  // Spend path: block wallet debits while an admin is impersonating.
613	  await assertNotImpersonating();
614	  const { user, server } = await ownedServer(serverId);
615	  if (server.isFree || !server.expiresAt) return;
616	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
617	  if (!plan) return;
618	  const term = vpsTerm(server.termMonths);
619	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
620	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
621	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
622	    where: { serverId }, select: { id: true },
623	  }));
624	  // Extra root disk renews at the current per-GB price on top of the plan, exactly
625	  // like worker/billing.ts — the two renewal paths must never disagree.
626	  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
627	  const extraDiskCents = extraDiskMonthly * term.months;
628	  const renewCents =
629	    vpsTermPriceCents(plan.priceCents, term.months) +
630	    (hasDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0) +
631	    extraDiskCents;
632	  const owner = await db.user.findUnique({ where: { id: server.userId } });
633	  if (!owner || owner.balanceCents < renewCents) {
634	    return { error: "Insufficient balance — top up your wallet first." };
635	  }
636	
637	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
638	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
639	  // can't both read E, both debit, and both write E+term (double-charge, one
640	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
641	  const E = server.expiresAt;
642	  const base = new Date(Math.max(E.getTime(), Date.now()));
643	  const newExpiry = addMonths(base, term.months);
644	  try {
645	    await db.$transaction(async (tx) => {
646	      // Compare-and-swap the expiry first; if it no longer equals E another
647	      // renewal already advanced it — bail without charging (tx rolls back).
648	      const adv = await tx.server.updateMany({
649	        where: { id: serverId, expiresAt: E },
650	        data: { expiresAt: newExpiry, suspendedNote: null, suspendReason: null },
651	      });
652	      if (adv.count === 0) throw new AlreadyRenewedError();
653	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
654	      await debitWallet(tx, server.userId, renewCents);
655	      await tx.walletTransaction.create({
656	        data: {
657	          userId: server.userId,
658	          amountCents: -renewCents,
659	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
660	        },
661	      });
662	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
663	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
664	      await tx.invoice.create({
665	        data: invoiceCreateData({
666	          userId: server.userId,
667	          description: `Renewal: ${plan.name} VPS (${server.hostname}) — ${term.label}`,
668	          status: "PAID",
669	          period: { start: E, end: newExpiry },
670	          lineItems: [
671	            {
672	              description: `${plan.name} VPS (${server.hostname}) — ${term.label}`,
673	              qty: 1,
674	              unitCents: renewCents - extraDiskCents,
675	              amountCents: renewCents - extraDiskCents,
676	            },
677	            ...(extraDiskCents > 0
678	              ? [
679	                  {
680	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
681	                    qty: 1,
682	                    unitCents: extraDiskCents,
683	                    amountCents: extraDiskCents,
684	                  },
685	                ]
686	              : []),
687	          ],
688	        }),
689	      });
690	    });
691	  } catch (e) {
692	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
693	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
694	    throw e;
695	  }
696	  await audit(user.id, "server.renew_now", serverId);
697	
698	  // An UNPAID-suspended server springs back to life once paid — but only that
699	  // kind. This used to fire for ANY suspended server, so a customer suspended for
700	  // outbound abuse could click "Renew now", pay, and put themselves straight back
701	  // on the network, undoing an abuse or admin action with a card. Legacy rows with
702	  // a null `suspendReason` are not auto-lifted; an admin can clear those by hand.
703	  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
704	    const pending = await db.job.count({
705	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
706	    });
707	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
708	  }
709	  revalidatePath(`/dashboard/servers/${serverId}`);
710	}
