/**
 * Months left on a term, clamped to something sane.
 *
 * The clamp matters on the CREDIT side: `renewNow` can stack `expiresAt` many
 * terms into the future, and an unclamped credit multiplies the monthly delta by
 * every stacked month. The client estimate already clamped to one term while the
 * server did not, so the two disagreed and the server was the generous one.
 */
export function remainingMonths(expiresAt: Date | null, now: number, capMonths?: number): number {
  if (!expiresAt) return 0;
  const raw = Math.max(0, (expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
  return capMonths && capMonths > 0 ? Math.min(raw, capMonths) : raw;
}

// Credit at the SAME effective rate the upgrade path charges at — term discount
// and promo applied — and clamp the remaining months to one term.
//
// The old maths credited the raw LIST-price delta over an UNCLAMPED duration,
// so it refunded more than the customer had ever paid (they bought at the
// term-discounted, promo-reduced price) and multiplied that by every month a
// stacked `renewNow` had pushed `expiresAt` into the future. On a 36-month term
// that is roughly a 20% cash windfall per downgrade before any promo. It has
// been unreachable only because the disk-monotonic guard blocks every downgrade
// the live catalogue permits — one cheap, storage-heavy plan would have turned
// it into a self-service money printer. Shared with the upgrade path through
// lib/proration.ts so the two directions can never drift apart again.
let creditCents = 0;
if (!server.isFree && server.expiresAt) {
  creditCents = prorateDowngradeCreditCents({
    fromMonthlyCents: server.plan.priceCents,
    toMonthlyCents: newPlan.priceCents,
    termMonths: server.termMonths,
    monthsRemaining: remainingMonths(server.expiresAt, Date.now(), server.termMonths),
  });
}

