  // is exactly where the bug lived: due 30 / balance 10 returned cardCents 20.
  for (const dueCents of DUES) {
    for (const balanceCents of BALANCES) {
      for (const useWallet of [true, false]) {
        const s = walletSplit({ dueCents, balanceCents, useWallet });
        assert.ok(
          s.cardCents === 0 || s.cardCents >= STRIPE_MIN_CENTS,
          `due ${dueCents}, balance ${balanceCents}, useWallet ${useWallet} -> card ${s.cardCents}`,
        );
      }
    }
  }
});

test("nothing is ever negative and the wallet is never over-drawn", () => {
  for (const dueCents of [...DUES, -100, -1]) {
    for (const balanceCents of [...BALANCES, -50]) {
      for (const useWallet of [true, false]) {
        const s = walletSplit({ dueCents, balanceCents, useWallet });
        assert.ok(s.walletApplied >= 0, `walletApplied ${s.walletApplied}`);
        assert.ok(s.cardCents >= 0, `cardCents ${s.cardCents}`);
        assert.ok(s.walletApplied <= Math.max(0, dueCents), "never apply more wallet than is owed");
        if (s.belowStripeMin) {
          // The one documented exception, and it is not an over-draw claim: the due
          // is under the card floor, so no card leg can exist and the wallet is the
          // only leg left. walletApplied is therefore the FULL due even when the
          // balance is short and even when useWallet is off, because no payable
          // split exists otherwise. The caller's guarded debitWallet decides whether
          // it clears; the flag is what tells the surface to say "top up first".
          assert.equal(s.walletApplied, Math.max(0, Math.round(dueCents)));
          assert.equal(s.cardCents, 0);
        } else if (useWallet) {
          assert.ok(
            s.walletApplied <= Math.max(0, balanceCents),
            `due ${dueCents}, balance ${balanceCents} -> wallet ${s.walletApplied} exceeds the balance`,
          );
        } else {
          assert.equal(s.walletApplied, 0, "wallet toggle off means no wallet is touched");
        }
      }
    }
  }
});

test("belowStripeMin is set exactly when the whole due is under the floor", () => {
  // The two flags describe opposite situations and the deploy wizard prints a
  // different line for each, so they must never both be true: clampedForStripeMin
  // means "a card leg exists and was raised to 50c", belowStripeMin means "no card
  // leg is possible at all". Conflating them would print "we'll charge $0.00 to
  // your card", which is the flavour of lie this suite exists to catch.
  for (const dueCents of DUES) {
    for (const balanceCents of BALANCES) {
      for (const useWallet of [true, false]) {
        const s = walletSplit({ dueCents, balanceCents, useWallet });
        assert.equal(
          s.belowStripeMin,
          dueCents > 0 && dueCents < STRIPE_MIN_CENTS,
          `due ${dueCents}, balance ${balanceCents}, useWallet ${useWallet}`,
        );
        assert.ok(
          !(s.belowStripeMin && s.clampedForStripeMin),
          "the two Stripe-floor flags are mutually exclusive",
        );
      }
    }
  }
});

