/**
 * FIXED 2026-07-26 (was a KNOWN GAP asserted against current behaviour).
 *
 * When the amount due is itself under Stripe's 50c floor, the clamp above has
 * nothing to work with — it lifts the card leg by moving cents off the wallet, and
 * a 30c charge cannot reach 50c however it is divided. This used to fall through
 * and return the raw sub-floor remainder (due 30 / balance 10 -> cardCents 20),
 * unflagged, and `createResizeCheckout` / `createDiskExpandCheckout` (lib/stripe.ts)
 * pass `cardCents` straight to Stripe with no floor guard — unlike the off-session
 * path, which does check (lib/stripe-cards.ts:523) — so the customer got a thrown
 * server action. Reachable via a few-cent resize proration late in a term.
 *
 * The card leg is now dropped entirely and the wallet takes the whole amount, since
 * inflating the card to 50c would charge more than is owed.
 */
test("a sub-floor due never produces a card leg — the wallet takes all of it", () => {
  const s = walletSplit({ dueCents: 30, balanceCents: 10, useWallet: true });
  assert.ok(s.cardCents >= STRIPE_MIN_CENTS || s.cardCents === 0, "the invariant that was broken");
  assert.equal(s.cardCents, 0, "no card charge is attempted for a sub-floor total");
  assert.equal(s.walletApplied, 30, "the wallet is the only leg that can settle 30c");
  assert.equal(s.walletApplied + s.cardCents, 30, "and the split still sums to the due exactly");
  assert.equal(s.belowStripeMin, true, "flagged, so the surface can say 'top up first'");
  assert.equal(s.clampedForStripeMin, false, "nothing was clamped UP to the floor here");
});

test("a sub-floor due the wallet fully covers is simply paid from the wallet", () => {
  const s = walletSplit({ dueCents: 30, balanceCents: 500, useWallet: true });
  assert.deepEqual(s, { walletApplied: 30, cardCents: 0, clampedForStripeMin: false, belowStripeMin: true });
});

test("a sub-floor due goes to the wallet even with the balance toggle off", () => {
  // `useWallet: false` normally means "put it all on the card", but a 30c card
  // charge does not exist as an option. Honouring the toggle would leave NO payable
  // split, so the toggle loses to the hard external constraint and the flag reports
  // it. Under the old code this returned cardCents 30 and Stripe rejected it.
  const s = walletSplit({ dueCents: 30, balanceCents: 500, useWallet: false });
  assert.equal(s.cardCents, 0, "a 30c card charge is not a thing Stripe will accept");
  assert.equal(s.walletApplied, 30);
  assert.equal(s.belowStripeMin, true);
});

test("the sub-floor boundary is exact at 49c and 50c", () => {
  const under = walletSplit({ dueCents: 49, balanceCents: 0, useWallet: true });
  assert.deepEqual(under, { walletApplied: 49, cardCents: 0, clampedForStripeMin: false, belowStripeMin: true });
  // At exactly the floor a card leg becomes possible again, so it is used.
  const at = walletSplit({ dueCents: 50, balanceCents: 0, useWallet: true });
  assert.deepEqual(at, { walletApplied: 0, cardCents: 50, clampedForStripeMin: false, belowStripeMin: false });
});

test("a sub-floor due is never inflated to reach the Stripe floor", () => {
  // The rejected alternative fix: charging 50c for a 30c debt. The customer must
  // never owe more than the quote, whatever Stripe's floor is.
  for (const dueCents of [1, 7, 25, 49]) {
    for (const balanceCents of [0, 5, 25, 1000]) {
      const s = walletSplit({ dueCents, balanceCents, useWallet: true });
      assert.equal(
        s.walletApplied + s.cardCents,
        dueCents,
        `due ${dueCents}, balance ${balanceCents}: the customer must owe exactly the due`,
      );
    }
  }
});

