test("a downgrade credit never exceeds what was paid, however many terms are stacked", () => {
  // This test used to bound a 108-month credit against ONE term's payment and
  // conclude that the uncapped figure was "free money". That is the wrong
  // denominator, and believing it is what justified capping the credit at one term
  // while the upgrade path charged for all 108 — the $362.88 asymmetry below.
  //
  // `expiresAt` only moves forward in exchange for payment: renewNow and the
  // auto-renew sweep each advance it by termMonths and charge vpsTermPriceCents for
  // exactly those months. So a customer sitting 108 months out on a 36-month term
  // has paid THREE terms, and the honest bound is per-month, not per-term.
  const now = new Date("2026-07-26T00:00:00.000Z").getTime();
  for (const stackedMonths of [36, 72, 108]) {
    const months = remainingMonths(new Date(now + stackedMonths * MS_PER_AVG_MONTH), now);

    // What those months actually cost. The renewal paths charge the term-discounted
    // price with NO promo applied, so this is the real cash the customer handed over
    // per remaining month on Max.
    const paidPerMonth = vpsTermPriceCents(MAX, TERM) / TERM;
    const paidForMonths = paidPerMonth * months;

    const credit = prorateDowngradeCreditCents({
      fromMonthlyCents: MAX,
      toMonthlyCents: STARTER,
      termMonths: TERM,
      monthsRemaining: months,
      promo: PROMO,
    });
    assert.ok(credit > 0, "the credit must actually move money, or this proves nothing");
    assert.ok(
      credit < paidForMonths,
      `${stackedMonths}mo stacked: credit ${credit} must stay under the ${Math.round(paidForMonths)} paid`,
    );
    // The bound holds structurally, not by luck: the credit is the DIFFERENCE between
    // two positive effective rates, so it is strictly less than the old plan's rate
    // over the same months no matter how many months there are. It holds with no
    // promo running too, which is the worst case for the platform.
    const undiscounted = prorateDowngradeCreditCents({
      fromMonthlyCents: MAX,
      toMonthlyCents: STARTER,
      termMonths: TERM,
      monthsRemaining: months,
      promo: NO_PROMO,
    });
    assert.ok(
      undiscounted < paidForMonths,
      `${stackedMonths}mo stacked, no promo: credit ${undiscounted} vs ${Math.round(paidForMonths)} paid`,
    );
  }
});

test("a stacked expiry round-trips to zero — the $362.88 cap asymmetry", () => {
  // THE BUG, fixed 2026-07-26. A customer on a 12-month term who hit "Renew now"
  // until `expiresAt` sat 36 months out: lib/resize.ts priced the upgrade over all
  // 36 remaining months while lib/actions-server-lifecycle.ts capped the credit at
  // 12, so Starter -> Max -> Starter charged $544.32, refunded $181.44, and the
  // platform kept $362.88 of months the customer had genuinely bought.
  const TERM_12 = 12;
  const now = new Date("2026-07-26T00:00:00.000Z").getTime();
  const stacked = new Date(now + 36 * MS_PER_AVG_MONTH);
  const months = remainingMonths(stacked, now);
  assert.ok(months > 35.99 && months < 36.01, `three stacked 12-month terms, got ${months}`);

  const up = prorateUpgradeCents({
    fromMonthlyCents: STARTER,
    toMonthlyCents: MAX,
    termMonths: TERM_12,
    monthsRemaining: months,
    promo: PROMO,
  });
  const down = prorateDowngradeCreditCents({
