    toMonthlyCents: STARTER,
    termMonths: TERM_12,
    monthsRemaining: months,
    promo: PROMO,
  });
  assert.equal(up, 54432, "the charge is unchanged — it was always the honest figure");
  assert.equal(down, up, "and the credit now mirrors it exactly, cent for cent");

  // The old capped credit, reproduced to keep the size of the hole on the record.
  const oldCappedCredit = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM_12,
