test("remainingMonths reports the whole remaining term and has no cap knob", () => {
  const now = new Date("2026-07-26T00:00:00.000Z").getTime();
  const threeTerms = new Date(now + 36 * MS_PER_AVG_MONTH);
  assert.ok(remainingMonths(threeTerms, now) > 35.99, "the raw remainder, uncapped");
  assert.ok(remainingMonths(new Date(now + 6 * MS_PER_AVG_MONTH), now) < 6.001);

  // `capMonths` used to be an optional third parameter, and it is exactly how the
  // upgrade and downgrade paths came to price different durations for the same
  // round trip. It is gone. If anyone re-adds it, a third argument would start
  // changing the answer again — so assert that it cannot.
  const withStrayArg = (remainingMonths as unknown as (e: Date, n: number, c?: number) => number)(
    threeTerms,
    now,
    12,
  );
  assert.equal(withStrayArg, remainingMonths(threeTerms, now), "no third argument may change the answer");
  assert.equal(remainingMonths.length, 2, "remainingMonths takes exactly (expiresAt, now)");
});

