  // asymmetry as intended behaviour. Four call sites had to agree on an optional
  // argument by convention and they did not, so a stacked expiry charged $544.32 up
  // and credited $181.44 down. Both sides must now use the byte-identical call.
  const SERVER_CALL = "remainingMonths(server.expiresAt, Date.now())";
  const CLIENT_CALL = "remainingMonths(new Date(expiresAt), Date.now())";
  const sites: [string, string][] = [
    ["lib/resize.ts", SERVER_CALL],
    ["lib/actions-server-lifecycle.ts", SERVER_CALL],
    ["components/customer/ResizePicker.tsx", CLIENT_CALL],
    ["components/customer/ResizeDown.tsx", CLIENT_CALL],
  ];
  for (const [file, expected] of sites) {
    const src = readNormalized(file);
    assert.ok(src.includes(expected), `${file} must call \`${expected}\` — same duration, both directions`);
    // And no call site may reintroduce a third (cap) argument.
    assert.ok(
      !new RegExp(expected.replace(/[.()[\]]/g, "\\$&").replace(/\\\)$/, ",")).test(src),
      `${file} must not pass a cap to remainingMonths`,
    );
  }
});

