import assert from "node:assert/strict";
import {
  prorateUpgradeCents,
  prorateDowngradeCreditCents,
  remainingMonths,
  MS_PER_AVG_MONTH,
} from "/opt/nxeon/lib/proration.ts";
import { walletSplit, STRIPE_MIN_CENTS } from "/opt/nxeon/lib/wallet-split.ts";
import { currentPromo } from "/opt/nxeon/lib/promotions.ts";

const promo = currentPromo(new Date("2026-07-26T12:00:00.000Z"));
const now = new Date("2026-07-26T00:00:00.000Z").getTime();
// "Renew now" stacked to 36 months out on a 12-month term.
const stacked = new Date(now + 36 * MS_PER_AVG_MONTH);

// ---- BUG 1: the caller's verbatim failing assertion, with the cap arg gone ----
const up = prorateUpgradeCents({
  fromMonthlyCents: 899, toMonthlyCents: 3299, termMonths: 12,
  monthsRemaining: remainingMonths(stacked, now), promo,
});
const down = prorateDowngradeCreditCents({
  fromMonthlyCents: 3299, toMonthlyCents: 899, termMonths: 12,
  monthsRemaining: remainingMonths(stacked, now), promo,
});
assert.equal(up, down);
console.log(`BUG1 assertion: up=${up} down=${down} -> EQUAL (was 54432 !== 18144)`);

// Confirm the OLD capped credit really was the 18144 figure, i.e. the new test
// would have failed against the pre-fix code rather than passing trivially.
const oldCapped = prorateDowngradeCreditCents({
  fromMonthlyCents: 3299, toMonthlyCents: 899, termMonths: 12,
  monthsRemaining: Math.min(remainingMonths(stacked, now), 12), promo,
});
assert.equal(oldCapped, 18144);
assert.notEqual(up, oldCapped);
console.log(`BUG1 old behaviour reproduced: capped credit=${oldCapped}, hole=${up - oldCapped} (=$${((up - oldCapped) / 100).toFixed(2)})`);

// ---- BUG 2: the caller's verbatim failing assertion ----
const s = walletSplit({ dueCents: 30, balanceCents: 10, useWallet: true });
assert.ok(s.cardCents >= STRIPE_MIN_CENTS || s.cardCents === 0);
assert.equal(s.cardCents, 0);
console.log(`BUG2 assertion: cardCents=${s.cardCents} (was 20), walletApplied=${s.walletApplied}, belowStripeMin=${s.belowStripeMin}`);

// The floor postcondition as a total property over a wide grid, incl. sub-floor.
let checked = 0;
for (let due = 0; due <= 200; due++) {
  for (const bal of [0, 1, 5, 9, 10, 25, 29, 30, 49, 50, 51, 99, 149, 200, 5000]) {
    for (const useWallet of [true, false]) {
      const r = walletSplit({ dueCents: due, balanceCents: bal, useWallet });
      assert.ok(r.cardCents === 0 || r.cardCents >= STRIPE_MIN_CENTS,
        `due ${due} bal ${bal} uw ${useWallet} -> card ${r.cardCents}`);
      assert.equal(r.walletApplied + r.cardCents, due, `sum broke at due ${due} bal ${bal}`);
      assert.ok(!(r.belowStripeMin && r.clampedForStripeMin), "flags must be exclusive");
      checked++;
    }
  }
}
console.log(`BUG2 floor + sum postconditions hold across ${checked} input combinations`);

// ---- Round-trip symmetry across many stacked expiries and terms ----
for (const term of [1, 12, 24, 36]) {
  for (const stackMonths of [1, 6, 12, 36, 72, 108]) {
    const m = remainingMonths(new Date(now + stackMonths * MS_PER_AVG_MONTH), now);
    const u = prorateUpgradeCents({ fromMonthlyCents: 899, toMonthlyCents: 3299, termMonths: term, monthsRemaining: m, promo });
    const d = prorateDowngradeCreditCents({ fromMonthlyCents: 3299, toMonthlyCents: 899, termMonths: term, monthsRemaining: m, promo });
    assert.equal(u, d, `term ${term}, ${stackMonths}mo stacked: ${u} vs ${d}`);
  }
}
console.log("Round trip nets to zero for every term x stacked-expiry combination");

